from pathlib import Path
import csv, json, math, re
from datetime import datetime, timezone
from zoneinfo import ZoneInfo
import pandas as pd

base = Path('/app/dataset')
cal = json.loads((base/'sensors_calibration.json').read_text())['enterprise_platform']['deployment_environments']['system_config']['farms']
farms_df = pd.read_csv(base/'farms.csv')
reg_df = pd.read_csv(base/'farm_registry.csv')
farms_df['farm_name_norm'] = farms_df['farm_name'].str.strip().str.lower()
reg_df['farm_name_norm'] = reg_df['farm_name'].str.strip().str.lower()
meta_df = reg_df.merge(farms_df[['farm_name_norm','timezone']], on='farm_name_norm', how='left')
notes = (base/'maintenance_notes.txt').read_text()
maint = {}
for line in notes.splitlines():
    if 'Status: COMPLETED.' not in line:
        continue
    for pat in [r'on (.+?) on the (\d+)(?:st|nd|rd|th) of March from (\d{2}:\d{2}) to (\d{2}:\d{2}) local time\.', r'at (.+?) on March (\d+), starting at (\d{2}:\d{2}) and finishing at (\d{2}:\d{2}) local time\.']:
        m = re.search(pat, line, re.I)
        if m:
            farm_name, day, start_t, end_t = m.groups()
            row = meta_df[meta_df['farm_name_norm'] == farm_name.strip().lower()].iloc[0]
            tz = ZoneInfo(row['timezone'])
            s = datetime(2024,3,int(day), *map(int,start_t.split(':')), tzinfo=tz).astimezone(timezone.utc).replace(tzinfo=None)
            e = datetime(2024,3,int(day), *map(int,end_t.split(':')), tzinfo=tz).astimezone(timezone.utc).replace(tzinfo=None)
            maint.setdefault(row['farm_id'], []).append((s,e))
            break

fmts=['%Y-%m-%d %H:%M:%S','%d.%m.%Y %H:%M:%S']

def parse_ts(s):
    s=str(s).strip()
    for fmt in fmts:
        try:
            return datetime.strptime(s, fmt)
        except Exception:
            pass
    return pd.NaT

def parse_num(s):
    if s is None:
        return math.nan
    s=str(s).strip()
    if not s:
        return math.nan
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')
    try:
        return float(s)
    except Exception:
        return math.nan

uf={'kwh':1,'wh':1/1000,'mwh':1000,'btu':0.00029307107}
nu=lambda u: ''.join(ch.lower() for ch in u if ch.isalpha())
start=datetime(2024,3,15)
end=datetime(2024,3,16)
ans={}
for farm_id, cfg in sorted(cal.items()):
    raw=(base/f'production_{farm_id}.csv').read_bytes()
    enc='utf-16' if b'\x00' in raw[:200] else 'utf-8'
    lines=raw.decode(enc).splitlines()
    header_idx=next(i for i,l in enumerate(lines) if l.strip().lower().startswith('timestamp'))
    delim=';' if ';' in lines[header_idx] else ','
    rows=list(csv.reader(lines[header_idx:], delimiter=delim))
    cols=rows[0]; body=rows[1:]
    df=pd.DataFrame(body, columns=cols).drop_duplicates()
    df['ts']=df.iloc[:,0].map(parse_ts)
    df=df[df['ts'].notna()].sort_values('ts', kind='stable')
    df=df.drop_duplicates(subset=['ts'], keep='last')
    df['temp']=df['inverter_temperature_C'].map(parse_num)
    val_idx=cols.index(cfg['calibration_data']['value_column_name'])
    df['raw']=df.iloc[:, val_idx].map(parse_num)
    # safety none >85 in dataset, but implement anyway
    spikes=df.loc[df['temp']>85,'ts'].tolist()
    if spikes:
        mask=pd.Series(False, index=df.index)
        for ts in spikes:
            mask |= (df['ts']>ts) & (df['ts']<=ts + pd.Timedelta(minutes=45))
        df=df.loc[~mask]
    df=df[(df['ts']>=start)&(df['ts']<end)]
    for s,e in maint.get(farm_id,[]):
        df=df[~((df['ts']>=s)&(df['ts']<e))]
    df=df[df['raw'].notna()]
    df['true']=df['raw'] - cfg['calibration_data']['calibration_offset']
    df=df[df['true']>=0]
    if cfg['sensor_info']['reading_type'].lower()=='energy':
        total=df['true'].sum()*uf[nu(cfg['sensor_info']['unit'])]
    else:
        cadence=df['ts'].sort_values().drop_duplicates().diff().dropna().dt.total_seconds().div(3600)
        cadence=(cadence[cadence>0].mode().iloc[0] if not cadence.empty else 0)
        total=df['true'].sum()*cadence
    ans[farm_id]=round(float(total))
print(ans)
